struct Fuera {};
int revisiones = 0;

int revisar(int entrada) {
    ++revisiones;
    if (entrada < 0 || entrada > 9) {
        throw Fuera{};
    }

    return 9 - entrada;
}

bool aplicar_revision(int& estado, int entrada) noexcept;
bool aplicar_revision(int& estado, int entrada) noexcept {
    // Completa la revisión y el tratamiento de Fuera dentro de esta función.
    (void)estado;
    (void)entrada;
    return false;
}

int main() {
    int cantidad = 0;
    if (!(std::cin >> cantidad) || cantidad < 1 || cantidad > 12) {
        return 1;
    }
    int estado = 4;
    std::cout << "Inicio:" << estado << ";Noexcept:"
              << noexcept(aplicar_revision(estado, 0))
              << ";Revisiones:" << revisiones << '\n';
    for (int i = 0; i < cantidad; ++i) {
        int entrada = 0;
        if (!(std::cin >> entrada)) {
            return 1;
        }
        const int antes = estado;
        const bool aceptado = aplicar_revision(estado, entrada);

        std::cout << "Resultado:" << aceptado << ";Antes:" << antes
                  << ";Actual:" << estado << ";Revisiones:"
                  << revisiones << '\n';
    }
    std::cout << "Final:" << estado << ";Revisiones:" << revisiones;

    return 0;
}

